using ArtifactUtils
using Pkg.Artifacts

const HETA_COMPILER_RELEASE = "v0.12.2"

const GENERATED_FILE_HEADER = """
# This file is generated by artifacts/generate_artifacts.jl.
# Do not edit it manually. Update artifact sources in that script, then run:
#   julia --project=artifacts artifacts/generate_artifacts.jl

"""

const DYNMS_SCHEMAS = Dict(
  "0.2.1" => "https://github.com/hetalang/heta-compiler/releases/download/v0.12.2/schemas.tar.gz",
  #"0.2.2" => "https://github.com/hetalang/heta-compiler/releases/download/v0.12.3/schemas.tar.gz", # for future version
)

const artifacts_toml = joinpath(@__DIR__, "..", "Artifacts.toml")

# heta-compiler does not publish an x86_64 (Intel) macOS build, only aarch64 (Apple Silicon).
platforms = [
  Artifacts.Platform("x86_64", "linux"),
  Artifacts.Platform("aarch64", "linux"),
  Artifacts.Platform("x86_64", "windows"),
  # Artifacts.Platform("x86_64", "macos"), # old arch, not available for heta-compiler >0.12.0
  Artifacts.Platform("aarch64", "macos")
]

rm(artifacts_toml; force = true)

for platform in platforms

  os  = platform.tags["os"]

  arch = platform.tags["arch"]
  if arch == "x86_64"
    arch = "x64"
  elseif arch == "aarch64"  
    arch = "arm64"
  else
    error("Unsupported architecture: $arch")
  end
    
  url = "https://github.com/hetalang/heta-compiler/releases/download/$HETA_COMPILER_RELEASE/heta-compiler-$os-$arch.tar.gz"

  println("Adding artifact for $platform")

  try
    add_artifact!(
        artifacts_toml,
        "heta_app",
        url;
        platform,
        force = true,
        lazy = false,
    )
  catch e
    error("Failed to add artifact for $platform from $url: $e")
  end
end

for (version, url) in DYNMS_SCHEMAS
  artifact_name = "dynms_schema_$version"
  println("Adding DynMS schema $version")

  try
    add_artifact!(
      artifacts_toml,
      artifact_name,
      url;
      force = true,
      lazy = false,
    )
  catch e
    error("Failed to add DynMS schema $version from $url: $e")
  end
end

write(artifacts_toml, GENERATED_FILE_HEADER * read(artifacts_toml, String))
